                        const name = hb[1].trim();
                        const digit = name.match(/(?:paragraph|¶)\s*(\d+)/i) || name.match(/^¶?\s*(\d+)$/);
                        para = digit ? digit[1] : (/introduction/i.test(name) ? 'Introduction'
                            : /conclusion/i.test(name) ? 'Conclusion' : name);
