        const contentWrap = el('div', { className: 'swml-canvas-content' });
        // v7.20.293: the container clips its children (overflow-x:hidden), so a docked rail panel
        // sized legally at drag time gets sliced off the moment the container narrows (chat-pane
        // drag, window resize). Re-clamp on every container resize. Writing a panel width cannot
        // change the container's own box, so this cannot feed back.
        try {
            if (window.ResizeObserver) new ResizeObserver(_swmlReclampDockedPanels).observe(contentWrap);
        } catch (_) {}
        // v7.19.213: Add codex class so CSS counter scope offsets section numbering
        // (About the Codex = 0, Unit 1 children = 1.1, 1.2, ...). Pairs with
        // .swml-codex-doc counter-reset rule in wml-canvas.css.
        const _isCodexDoc = state.task === 'mastery_codex';
        // v7.19.252 (Fix F): per-stage class drives progressive section-reveal CSS.
        // Planning shows plan sections only; outlining adds outline + response; polishing
        // unchanged from outlining (refines existing); reassessment adds feedback + scores
        // + signoff. The doc HTML stays cumulative (Model B copy-forward keeps the full
        // scaffold intact) — only the VIEW differs per stage via CSS in wml-canvas.css.
        // task='assessment' + phase='redraft' = the collapsed reassessment; resolve to
        // 'reassessment' for the stage class so it's distinct from Phase 1 assessment.
        const _stageTask = (state.task === 'assessment' && state.phase === 'redraft') ? 'reassessment' : state.task;
        const _stageCls = (_stageTask && ['planning','outlining','polishing','reassessment'].includes(_stageTask))
            ? ' swml-stage-' + _stageTask
            : '';
        const docWrap = el('div', { className: 'swml-canvas-doc' + (_isCodexDoc ? ' swml-codex-doc' : '') + _stageCls });
        const editorEl = el('div', { id: 'swml-tiptap-editor' });
        // v7.19.467: stamp the editor with the LESSON (post id) it was mounted in.
        // saveCanvasContent refuses to persist this editor's content once the user has
        // navigated to a DIFFERENT lesson — closing the SPA-nav race where state.task
        // flips to the incoming lesson before the editor is rebuilt and a save lands the
        // OLD doc under the NEW key (CW Step-3 logline doc → _cw_2). We key on post id, not
        // state.task, because task is legitimately coerced in-place within a single render
        // (diagnostic/''→'assessment') — those must still save (same lesson, same post id).
        editorEl._swmlBuiltForPost = (window.swmlEmbedConfig && window.swmlEmbedConfig.postId) || 0;
        const gutterWrap = el('div', { className: 'swml-comment-gutter' });
        docWrap.appendChild(editorEl);
        docWrap.appendChild(gutterWrap);
        // docWrap appended after outline elements (below) for sticky to work

        // ── Document Outline ──
        // v7.20.304: rail icons move from 2px strokes to Phosphor Fill (MIT, path data taken
        // verbatim from phosphor-icons/core — not redrawn). Solid shapes are what make the
        // hover colour-flood read as an app tile; a hairline stroke leaves the chip looking
        // empty when the colour sweeps over it.
        const SVG_OUTLINE = '<svg width="16" height="16" viewBox="0 0 256 256" fill="currentColor"><path d="M208,32H48A16,16,0,0,0,32,48V208a16,16,0,0,0,16,16H208a16,16,0,0,0,16-16V48A16,16,0,0,0,208,32ZM68,188a12,12,0,1,1,12-12A12,12,0,0,1,68,188Zm0-48a12,12,0,1,1,12-12A12,12,0,0,1,68,140Zm0-48A12,12,0,1,1,80,80,12,12,0,0,1,68,92Zm124,92H104a8,8,0,0,1,0-16h88a8,8,0,0,1,0,16Zm0-48H104a8,8,0,0,1,0-16h88a8,8,0,0,1,0,16Zm0-48H104a8,8,0,0,1,0-16h88a8,8,0,0,1,0,16Z"/></svg>';

        // v7.13.53: Wrap outline + resources buttons in a sticky column
        const btnColumn = el('div', { className: 'swml-outline-btn-column' });

        // v7.20.302: rail icon hover-reveal — give every rail button a second, coloured
        // copy of its own icon for the clip-path wipe (styling in wml-canvas.css).
        //
        // OBSERVED rather than wired per button, deliberately. The rail is assembled across
        // eight separate appendChild sites spread over ~3,500 lines (outline, collapse,
        // resources, writer's profile, story components, story spine, prior attempts,
        // comparison poem), several of them conditional. Calling a helper after each one is
        // exactly the "new sibling silently misses the behaviour" class this codebase keeps
        // hitting — a rail button added later would just quietly not have the effect, with
        // no error. Watching the column instead means the behaviour is a property of BEING a
        // rail button, so anything added in future inherits it for free.
        (function installRailHueLayer(column) {
            const addHueLayer = (btn) => {
                if (!btn || typeof btn.querySelector !== 'function') return;
                // Idempotent — a re-render must not stack a third and fourth copy.
                if (btn.querySelector(':scope > svg.swml-rail-hue')) return;
                const base = btn.querySelector(':scope > svg');
                if (!base) return;
                const dup = base.cloneNode(true);
                dup.classList.add('swml-rail-hue');
                // The icon is decorative twice over — the button already carries aria-label,
                // and without this every rail control announces its icon a second time.
                dup.setAttribute('aria-hidden', 'true');
                dup.setAttribute('focusable', 'false');
                dup.removeAttribute('style');   // e.g. the header icons' inline opacity
                btn.appendChild(dup);
            };
            column.querySelectorAll('.swml-outline-btn').forEach(addHueLayer);
            try {
                new MutationObserver((records) => {
                    records.forEach((rec) => {
                        rec.addedNodes.forEach((node) => {
                            if (!node || node.nodeType !== 1 || !node.classList) return;
                            if (node.classList.contains('swml-outline-btn')) addHueLayer(node);
                        });
                    });
                }).observe(column, { childList: true });
            } catch (e) {
                console.warn('WML v7.20.302: rail hue observer unavailable', e && e.message);
            }
        })(btnColumn);

        // Floating trigger on left edge of content area
        const outlineBtn = el('button', {
            className: 'swml-outline-btn',
            'data-tooltip': 'Document Outline',
            'data-tooltip-pos': 'right',
            'aria-label': 'Document Outline',
            innerHTML: SVG_OUTLINE,
            onClick: (e) => { e.stopPropagation(); toggleOutlinePanel(); }
        });
        btnColumn.appendChild(outlineBtn);

        // v7.19.926 (Neil Run 9): collapse/expand EVERY collapsible section in one click.
        // Operates on the same .swml-collapsible capability class the chevrons stamp — any
        // future collapsible type is covered by construction (no section list). Persists
        // through the SAME localStorage keys the per-section toggle uses (page+label), so
        // reloads and the pop-out pad see one consistent state. Class toggle on the section
        // dom is the identical write the per-section chevron has done since v607 (PM-safe).
        const SVG_COLLAPSE_ALL = '<svg width="16" height="16" viewBox="0 0 256 256" fill="currentColor"><path d="M90.34,69.66A8,8,0,0,1,96,56h24V16a8,8,0,0,1,16,0V56h24a8,8,0,0,1,5.66,13.66l-32,32a8,8,0,0,1-11.32,0Zm43.32,84.68a8,8,0,0,0-11.32,0l-32,32A8,8,0,0,0,96,200h24v40a8,8,0,0,0,16,0V200h24a8,8,0,0,0,5.66-13.66ZM216,120H40a8,8,0,0,0,0,16H216a8,8,0,0,0,0-16Z"/></svg>';
        const collapseAllBtn = el('button', {
            className: 'swml-outline-btn swml-collapse-all-btn',
            'data-tooltip': 'Collapse / expand all sections',
            'data-tooltip-pos': 'right',
            'aria-label': 'Collapse or expand all sections',
            innerHTML: SVG_COLLAPSE_ALL,
            onClick: (e) => {
                e.stopPropagation();
                try {
                    const secs = Array.from(document.querySelectorAll('#swml-tiptap-editor .swml-section-block.swml-collapsible'));
                    if (!secs.length) return;
                    const collapse = secs.some(s => !s.classList.contains('swml-fb-collapsed')); // any open → collapse all; all closed → expand all
                    secs.forEach(s => {
                        s.classList.toggle('swml-fb-collapsed', collapse);
                        try {
                            const lbl = s.getAttribute('data-section-label') || '';
                            if (lbl) localStorage.setItem('swml_fbcollapse:' + location.pathname + ':' + lbl, collapse ? '1' : '0');
                        } catch (_) { /* storage off */ }
                    });
                    try { if (window.WML && window.WML.renderAnalyticsReadout) window.WML.renderAnalyticsReadout(); } catch (_) { /* best-effort */ }
                    console.log('[WML] collapse-all →', collapse ? 'collapsed' : 'expanded', secs.length, 'sections');
                } catch (err) { console.warn('WML collapse-all: skipped —', err && err.message); }
            }
        });
        btnColumn.appendChild(collapseAllBtn);

        // Panel
        const outlinePanel = el('div', { className: 'swml-outline-panel' });
