            // styles + body parentage clear and the panel can hide cleanly.
            // Otherwise the close-class toggle fires but inline position:fixed
            // + size styles keep the panel visible — looks "jammed".
            if (!next && outlineCtl.isFloating()) {
                dockOutline();
            }
            outlineOpen = next;
