                    + (String(first.board || '').toUpperCase() + ' · ' + _paTextName(first.text)).replace(/[<>&]/g, c => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;' }[c]))
                    + ' <span class="swml-prior-group-count">' + groups[gk].length + '</span>';
