            language2:        { format: 'multi_question', marks: 80, aos: 'AO1,AO2,AO3,AO5,AO6' },
            language_p1:      { format: 'multi_question', marks: 80, aos: 'AO1,AO2,AO4,AO5,AO6' },
            language_p2:      { format: 'multi_question', marks: 80, aos: 'AO1,AO2,AO3,AO5,AO6' },
