            modern_prose:     { format: 'dual', partA: { marks: 20, aos: 'AO1,AO2' }, partB: { marks: 20, aos: 'AO1,AO2' }, hasExtract: true },
            poetry_anthology: { format: 'dual', partA: { marks: 20, aos: 'AO1,AO2' }, partB: { marks: 20, aos: 'AO1,AO2' } },
