            poetry_anthology: { format: 'either_or', marks: 40, aos: 'AO1,AO2,AO3' },
            language1:        { format: 'multi_question', marks: 80, aos: 'AO1,AO2,AO5,AO6' },
            language2:        { format: 'multi_question', marks: 80, aos: 'AO1,AO2,AO5,AO6' },
